<template><div class="page"><div><h1 class="page-title">群聊管理</h1><p class="page-subtitle">全局查看群聊活跃度、Agent 状态与内容风险</p></div><section class="app-card"><div class="filters"><div class="search"><Search :size="15"/><input v-model="q" placeholder="搜索群聊 / Room ID" @keyup.enter="load"/></div><select v-model="sort" class="select" @change="load"><option value="active">活跃度排序</option><option value="members">成员数排序</option><option value="created">创建时间排序</option></select><button class="btn" @click="load">查询</button><StatusBadge :tone="error?'danger':'success'" dot>{{error?'接口异常':`共 ${total} 个群聊`}}</StatusBadge></div><div class="table-wrap"><table class="data-table"><thead><tr><th>群聊</th><th>群主</th><th>成员</th><th>在线</th><th>今日消息</th><th>Agent</th><th>违规</th><th>最后活跃</th><th></th></tr></thead><tbody><tr v-for="r in rooms" :key="r.id"><td><b>{{r.name||r.room_name||`Room #${r.id}`}}</b><small>#{{r.id}}</small></td><td>{{r.owner||r.owner_name||'—'}}</td><td>{{r.members??0}}</td><td>{{r.online??0}}</td><td>{{fmt(r.messages_today)}}</td><td><StatusBadge :tone="r.agent?'success':'neutral'" dot>{{r.agent?'启用':'关闭'}}</StatusBadge></td><td><span :class="r.violations?'risk':''">{{r.violations??0}}</span></td><td class="muted">{{formatTime(r.last_active)}}</td><td><div class="actions"><button class="btn btn-sm" @click="detail(r)">详情</button><button class="btn btn-danger btn-sm" @click="remove(r)"><Trash2 :size="13"/>解散</button></div></td></tr><tr v-if="!rooms.length"><td colspan="9" class="empty">{{error||'暂无群聊数据'}}</td></tr></tbody></table></div></section><dialog ref="dialog" class="detail-dialog"><div v-if="selected"><header><div><b>{{selected.name||selected.room_name||`Room #${selected.id}`}}</b><span>#{{selected.id}}</span></div><button class="icon-btn" @click="dialog?.close()">×</button></header><pre>{{JSON.stringify(selected,null,2)}}</pre></div></dialog></div></template>
<script setup>import{onMounted,ref}from'vue';import{Search,Trash2}from'lucide-vue-next';import StatusBadge from'../../components/common/StatusBadge.vue';import{adminApi}from'../../api/admin.js';const rooms=ref([]),q=ref(''),sort=ref('active'),error=ref(''),total=ref(0),dialog=ref(),selected=ref(null);const fmt=v=>v==null?'—':new Intl.NumberFormat('zh-CN',{notation:Number(v)>9999?'compact':'standard'}).format(v);const formatTime=v=>v?new Date(v).toLocaleString('zh-CN'):'—';async function load(){error.value='';try{const d=await adminApi.rooms({q:q.value,sort:sort.value,page_size:100});rooms.value=Array.isArray(d)?d:(d?.items||d?.rooms||[]);total.value=d?.total??rooms.value.length}catch(e){rooms.value=[];error.value=e.message}}async function detail(r){try{selected.value=await adminApi.room(r.id)}catch{selected.value=r}dialog.value?.showModal()}async function remove(r){if(!confirm(`确定强制解散「${r.name||r.room_name||r.id}」？`))return;try{await adminApi.deleteRoom(r.id);await load()}catch(e){alert(e.message)}}onMounted(load)</script>
<style scoped>.page{display:grid;gap:16px}.filters{padding:14px;display:flex;gap:10px;align-items:center}.search{height:38px;width:320px;display:flex;align-items:center;gap:8px;padding:0 11px;border:1px solid var(--line-strong);border-radius:9px;color:var(--text-3)}.search input{border:0;outline:0;background:transparent;color:var(--text);width:100%}.select{width:160px}td small{display:block;color:var(--text-3);font-size:10px;margin-top:3px}.risk{color:var(--danger);font-weight:700}.actions{display:flex;justify-content:flex-end;gap:6px}.empty{text-align:center!important;color:var(--text-3);padding:30px!important}.detail-dialog{width:min(660px,90vw);border:1px solid var(--line);border-radius:14px;background:var(--surface);color:var(--text);padding:0}.detail-dialog::backdrop{background:rgba(10,18,32,.45)}.detail-dialog header{display:flex;justify-content:space-between;align-items:center;padding:16px 18px;border-bottom:1px solid var(--line)}.detail-dialog header span{display:block;color:var(--text-3);font-size:10px;margin-top:3px}.detail-dialog pre{margin:0;padding:18px;max-height:65vh;overflow:auto;font-size:11px}</style>
